class Solution {
    public int[] diStringMatch(String s){
        int[] answer=new int[s.length()+1];
        int low=0,high=s.length();
        for(int i=0;i<s.length();i++)answer[i]=s.charAt(i)=='I'?low++:high--;
        answer[s.length()]=low;
        return answer;
    }
}

code.kotlin:
class Solution {
    fun diStringMatch(s:String):IntArray{
        val answer=IntArray(s.length+1);
        var low=0;
        var high=s.length;
        for(i in s.indices)answer[i]=if(s[i]=='I')low++ else high--;
        answer[s.length]=low;
        return answer
    }
}

